// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        // Ensure the caller is not the rewardDistributor (assume to avoid trivial cases)
        vm.assume(caller != address(this));

        // Record initial distributor
        address distributorBefore = c.rewardDistributor();

        // Attempt to call addReward as a non-distributor
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("addReward(address)", address(0x1)));

        // Assert: the call must revert because caller is not the rewardDistributor
        assertTrue(!success);

        // Also ensure the distributor hasn't changed (this is redundant but extra safety)
        address distributorAfter = c.rewardDistributor();
        assertTrue(distributorAfter == distributorBefore);
    }
}

